   const icon=paths=>'<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths+'</svg>';
   const timeIcon=icon('<circle cx="10" cy="12" r="7"/><path d="M10 8v4l2.5 1.5M20 5v6m-3-3h6"/>'),sendIcon=icon('<path d="m21 3-7 18-4-7-7-4 18-7ZM10 14 21 3"/>');
   host.classList.add('discussion-view');
   host.innerHTML='<div class="discussion-feed" data-d="feed" tabindex="0" role="region" aria-label="评论与训练视频"><div class="discussion-media"><div class="discussion-video-select"><label>训练赛视频<select data-d="watch-video" aria-label="选择训练赛视频"></select></label></div><p class="discussion-playing" data-d="media-current" role="status" hidden></p><div data-d="media"></div><details class="discussion-video-editor"><summary>添加 / 修改 B 站视频</summary><form data-d="video-form"><label>视频链接或 BV 号<input data-d="video-url" type="text" inputmode="url" maxlength="500" placeholder="https://www.bilibili.com/video/BV…"></label><button class="quiet-btn" type="submit">保存视频链接</button></form></details></div><div class="discussion-list" data-d="list"></div></div><button type="button" class="quiet-btn discussion-login" data-action="login">登录队员身份后参与讨论</button><form class="discussion-composer" data-d="form"><div class="discussion-context" data-d="context" hidden><div class="discussion-replying" data-d="reply-note" hidden></div><button type="button" class="quiet-btn" data-action="cancel" hidden>取消</button></div><div class="discussion-compose-row"><label><span data-d="composer-label" class="discussion-sr-only">写评论</span><textarea data-d="text" rows="1" maxlength="800" required placeholder="写下你的观察或心得…"></textarea></label><div class="discussion-submit"><button type="button" class="quiet-btn discussion-icon discussion-attach" data-d="attach" aria-label="添加视频时间点" title="添加视频时间点" aria-pressed="false" aria-expanded="false" aria-controls="'+host.id+'-time-fields">'+timeIcon+'</button><button class="primary discussion-icon" type="submit" data-d="submit" aria-label="发送评论" title="发送评论">'+sendIcon+'</button></div></div><div class="discussion-time-fields" id="'+host.id+'-time-fields" data-d="time-fields" hidden><label>'+(gameMode?'引用视频':'选择训练赛视频')+'<select data-d="attach-video" aria-label="评论引用的视频"></select></label><label>时间点<input data-d="time" inputmode="text" placeholder="01:25 或 85" aria-label="视频时间点"></label><label class="discussion-page">分 P<input data-d="page" type="number" min="1" max="1000" value="1" aria-label="视频分 P"></label><small>按播放器显示的进度手动填写，如 01:25 或 85（秒）；发布后可点击定位。</small></div><p data-d="status" class="discussion-status" role="status"></p></form>';
   const games=()=>gameMode?[entry]:entry.games;
